for i in range(1, n + 1):
    prefix_min = INF
    for j in range(1, m + 1):
        val = abs(a[i - 1] - b[j - 1])
        prefix_min = min(prefix_min, dp[i - 1][j])
        dp[i][j] = prefix_min + val


print(min(dp[n][1:]))

